<?php $page_title='Campaigns'; require 'layout.php';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$a=$_POST['action']??'';try{if($a==='add'){$pdo->prepare('INSERT INTO campaigns(title,description,target_meals,location,start_date,end_date,status,created_by) VALUES(?,?,?,?,?,?,?,?)')->execute([trim($_POST['title']),trim($_POST['description']),max(0,(int)$_POST['target_meals']),trim($_POST['location']),$_POST['start_date']?:null,$_POST['end_date']?:null,'active',user()['id']]);flash('success','Campaign created.');}elseif($a==='status'){$pdo->prepare('UPDATE campaigns SET status=? WHERE id=?')->execute([$_POST['status'],(int)$_POST['id']]);flash('success','Campaign status updated.');}}catch(Throwable $e){flash('error',$e->getMessage());}redirect('campaigns.php');}
$rows=$pdo->query('SELECT * FROM campaigns ORDER BY created_at DESC')->fetchAll();
?><section class="admin-page-head"><div><span class="kicker">ADMIN / CAMPAIGNS</span><h1>Campaigns</h1><p>Create and manage food rescue drives.</p></div></section><section class="admin-form-card"><h2>Create campaign</h2><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add"><label>Title<input name="title" required placeholder="Feed 500 people this weekend"></label><label>Target meals<input type="number" name="target_meals" min="0" required></label><label>Location<input name="location"></label><label>Start date<input type="date" name="start_date"></label><label>End date<input type="date" name="end_date"></label><label>Description<textarea name="description"></textarea></label><button class="btn primary">Create campaign</button></form></section><div class="campaign-admin-grid"><?php foreach($rows as $c):$pct=$c['target_meals']?min(100,round($c['raised_meals']/$c['target_meals']*100)):0;?><article class="campaign-admin-card"><span class="badge <?=badge_class($c['status'])?>"><?=e($c['status'])?></span><h3><?=e($c['title'])?></h3><p><?=e($c['description'])?></p><div class="progress"><span style="width:<?=$pct?>%"></span></div><small><?=intval($c['raised_meals'])?> / <?=intval($c['target_meals'])?> meals · <?=e($c['location']?:'Community')?></small><form method="post" class="inline-form campaign-status"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?=$c['id']?>"><select name="status"><option>draft</option><option>active</option><option>paused</option><option>completed</option></select><button class="mini-btn">Save</button></form></article><?php endforeach;?></div><?php require 'footer.php'; ?>
